<script lang="ts">
 import {onMount,onDestroy,untrack} from 'svelte';
 import Button from './Button.svelte';
 import SketchCanvas from './SketchCanvas.svelte';
 import {request,APIError} from './api';
 import type {Page,Version,Job,LockStatus,DriftPanel,RepairTarget} from './types';
 let {kind,page,api,lang,chapter,characterID='',writable=false,activeJob=null,t,onClose,onRestore,onJob,onDirty}:{kind:'history'|'sketch'|'lockfix';page:Page;api:string;lang:string;chapter:number;characterID?:string;writable?:boolean;activeJob?:Job|null;t:(key:string,args?:Record<string,string|number>)=>string;onClose:()=>void;onRestore:(v:Version)=>void;onJob:(j:Job)=>void;onDirty:(dirty:boolean)=>void}=$props();
 let versions=$state.raw<Version[]>([]),selected=$state<Version|null>(null),loading=$state(false),busy=$state(false),error=$state('');
 let source=$state('upload'),sketch=$state<Blob|null>(null),sourceURL=$state(''),strength=$state(.62),finish=$state('screentone');
 let status=$state<LockStatus|null>(null),name=$state(''),refs=$state.raw<{id:string;url:string;kind:string}[]>([]),chosen=$state<string[]>([]),drift=$state<DriftPanel|null>(null),afterURL=$state(''),afterScore=$state<number|undefined>(undefined);
 interface Quote {quote:{provider_id:string;model_id:string;placeholder:boolean;estimate:{usd?:number;gpu_seconds?:number};layers:number};model_name:string}
 let quote=$state<Quote|null>(null),quoteSeq=0,quoteAbort:AbortController|null=null,actionAbort:AbortController|null=null;
 const quoteText=$derived(!quote?t('control.quote_unavailable'):quote.quote.placeholder?t('control.quote_placeholder'):(quote.quote.estimate.usd||0)>0?t('control.quote',{route:quote.model_name,amount:new Intl.NumberFormat(lang,{style:'currency',currency:'USD',minimumFractionDigits:6,maximumFractionDigits:6}).format(quote.quote.estimate.usd||0)}):t('control.quote_local',{route:quote.model_name,seconds:Math.ceil(quote.quote.estimate.gpu_seconds||0)}));
 async function refreshQuote(){if(kind==='history'||!writable||kind==='lockfix'&&!choices.length){quote=null;return;}const n=++quoteSeq;quoteAbort?.abort();quoteAbort=new AbortController();quote=null;try{const signal=AbortSignal.any([quoteAbort.signal,AbortSignal.timeout(15000)]);const out=kind==='sketch'?await request<Quote>(`${base}/quote?kind=sketch`,'GET',undefined,signal):await request<Quote>(`${api}/lock/quote`,'POST',{character_id:characterID,targets:choices.map(d=>({page_id:d.page_id,panel_id:d.panel_id,layer_id:d.layer_id,version:d.version}))},signal);if(!dead&&n===quoteSeq)quote=out;}catch(e){if(n===quoteSeq)fail(e);}}
 $effect(()=>{void [kind,page.id,page.version,choices.map(d=>`${d.layer_id}:${d.version}`).join(','),writable];untrack(()=>void refreshQuote());});
 let file=$state<HTMLInputElement>();let dead=false,serial=0,abort:AbortController|null=null,handled='';
 const running=$derived(activeJob?.state==='queued'||activeJob?.state==='running');
 const base=$derived(`${api}/pages/${page.id}`);
 const choices=$derived(status?.drift.filter(d=>chosen.includes(d.layer_id))||[]);
 const title=$derived(t(kind==='history'?'control.history_inspector':`control.${kind}_title`,{name,number:page.number}));
 function fail(e:unknown){if(dead||e instanceof DOMException&&e.name==='AbortError')return;error=e instanceof APIError?e.message:t('error.network');}
 async function loadHistory(){const n=++serial;abort?.abort();abort=new AbortController();loading=true;error='';try{const out=await request<{versions:Version[]}>(`${base}/history`,'GET',undefined,AbortSignal.any([abort.signal,AbortSignal.timeout(15000)]));if(dead||n!==serial)return;versions=out.versions;selected=versions.find(v=>v.number<page.version)||versions[0]||null;}catch(e){fail(e);}finally{if(n===serial)loading=false;}}
 async function loadLock(keepComparison=false){if(!characterID){error=t('control.no_character');return;}const n=++serial;abort?.abort();abort=new AbortController();loading=true;try{const out=await request<{status:LockStatus;name:string;references:typeof refs}>(`${api}/lock/${characterID}`,'GET',undefined,AbortSignal.any([abort.signal,AbortSignal.timeout(15000)]));if(dead||n!==serial)return;status=out.status;name=out.name;refs=out.references;chosen=out.status.drift.filter(d=>!d.locked).slice(0,24).map(d=>d.layer_id);if(!keepComparison)drift=out.status.drift[0]||null;}catch(e){fail(e);}finally{if(n===serial)loading=false;}}
 function setSketch(blob:Blob|null){if(sourceURL)URL.revokeObjectURL(sourceURL);sketch=blob;sourceURL=blob?URL.createObjectURL(blob):'';afterURL='';onDirty(!!blob);}
 function pickFile(e:Event){const f=(e.currentTarget as HTMLInputElement).files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>16*1024*1024){error=t('control.sketch_invalid');return;}error='';setSketch(f);}
 async function ink(){if(!sketch||!writable||!quote||running||busy)return;busy=true;error='';actionAbort?.abort();actionAbort=new AbortController();const signal=AbortSignal.any([actionAbort.signal,AbortSignal.timeout(30000)]);try{const form=new FormData();form.append('file',sketch,'sketch.png');form.append('base_version',String(page.version));const uploaded=await request<{id:string}>(`${base}/sketch`,'POST',form,signal);if(dead)return;const out=await request<{job:Job}>(`${base}/regenerate`,'POST',{base_version:page.version,sketch_asset_id:uploaded.id,strength,finish},signal);if(dead)return;onDirty(false);onJob(out.job);}catch(e){fail(e);}finally{if(!dead)busy=false;}}
 async function repair(){if(!choices.length||!writable||!quote||running||busy)return;busy=true;error='';try{const targets:RepairTarget[]=choices.map(d=>({page_id:d.page_id,panel_id:d.panel_id,layer_id:d.layer_id,version:d.version}));const out=await request<{job:Job}>(`${api}/lock/repair`,'POST',{character_id:characterID,targets},AbortSignal.timeout(30000));if(!dead)onJob(out.job);}catch(e){fail(e);}finally{if(!dead)busy=false;}}
 async function finishJob(j:Job){if(kind==='sketch'){afterURL=`${base}/proof?v=${page.version}&job=${j.id}`;return;}if(kind==='lockfix'&&drift){try{const out=await request<{page:Page}>(`${api}/pages/${drift.page_id}`,'GET',undefined,AbortSignal.timeout(15000));if(dead)return;const layer=out.page.panels.find(p=>p.id===drift!.panel_id)?.layers.find(l=>l.id===drift!.layer_id);afterURL=layer?.asset?.url||'';afterScore=layer?.lock_score;await loadLock(true);}catch(e){fail(e);}}}
 function toggle(d:DriftPanel){if(d.locked)return;if(chosen.includes(d.layer_id))chosen=chosen.filter(id=>id!==d.layer_id);else if(chosen.length<24)chosen=[...chosen,d.layer_id];}
 $effect(()=>{if(kind==='history'){void page.version;untrack(()=>void loadHistory());}});
 $effect(()=>{const j=activeJob;if(j?.state==='done'&&j.id!==handled){handled=j.id;untrack(()=>void finishJob(j));}});
 onMount(()=>{if(kind==='lockfix')void loadLock();});
 onDestroy(()=>{dead=true;serial++;abort?.abort();quoteAbort?.abort();actionAbort?.abort();if(sourceURL)URL.revokeObjectURL(sourceURL);onDirty(false);});
</script>
<section class="mv-ed__stage mv-control__stage" aria-label={title}>
 {#if error}<div class="mv-notice mv-notice--error" role="alert"><i class="ti ti-alert-triangle" aria-hidden="true"></i><p>{error}</p><Button small onclick={()=>kind==='history'?void loadHistory():kind==='lockfix'?void loadLock():void refreshQuote()}>{t('refresh')}</Button></div>{/if}
 <div class={`mv-control__pair mv-control__pair--${kind}`}>
  <figure><figcaption>{kind==='history'?t('control.main_now'):kind==='sketch'?t('control.your_sketch'):t('control.drift_before',{panel:drift?`${drift.page_number}.${drift.panel_number}`:'—',score:drift?Math.round(drift.score*100):'—'})}</figcaption>
   {#if kind==='history'}<img src={`${base}/proof?v=${page.version}`} alt={t('control.current_page',{number:page.number})}/>
   {:else if kind==='sketch'&&source==='draw'}<SketchCanvas ratio={page.width/page.height} {t} disabled={busy||running||!writable} onChange={setSketch}/>
   {:else if kind==='sketch'&&sourceURL}<img src={sourceURL} alt={t('control.your_sketch')}/>
   {:else if kind==='lockfix'&&drift?.url}<img class="mv-control__character-art" src={drift.url} alt={t('control.character_before',{name})}/>
   {:else}<div class="mv-control__placeholder"><i class={`ti ti-${kind==='sketch'?'upload':'lock'}`} aria-hidden="true"></i><p>{t(kind==='sketch'?'control.upload_hint':'control.no_drift')}</p>{#if kind==='sketch'}<Button onclick={()=>file?.click()} disabled={!writable}>{t('control.upload')}</Button>{/if}</div>{/if}
  </figure>
  {#if kind!=='history'}<i class="ti ti-arrow-right mv-control__arrow" aria-hidden="true"></i>{/if}
  <figure><figcaption>{kind==='history'?selected?t('control.snapshot',{number:selected.number}):t('history.empty'):kind==='sketch'?t('control.inked',{strength:new Intl.NumberFormat(lang,{minimumFractionDigits:2,maximumFractionDigits:2}).format(strength)}):t('control.after_fix',{score:afterScore===undefined?t('control.unscored'):Math.round(afterScore*100)+'%'})}</figcaption>
   {#if kind==='history'&&selected}<img src={`${base}/versions/${selected.id}?image=1`} alt={t('control.snapshot',{number:selected.number})}/>
   {:else if afterURL}<img class:mv-control__character-art={kind==='lockfix'} class:mv-control__pass={kind==='lockfix'&&afterScore!==undefined&&afterScore>=.9} class:mv-control__fail={kind==='lockfix'&&afterScore!==undefined&&afterScore<.9} src={afterURL} alt={t(kind==='sketch'?'control.inked_result':'control.character_after',{name})}/>
   {:else}<div class="mv-control__placeholder"><i class={`ti ti-${running?'loader-2':kind==='history'?'history':'brush'}`} aria-hidden="true"></i><p>{t(running?'control.generating':kind==='history'?'history.empty':'control.result_pending')}</p></div>{/if}
  </figure>
 </div>
</section>
<aside class="mv-ed__right mv-control__inspector">
 <div class="mv-ed__section-head mv-ed__inspector-head"><div><strong>{title}</strong><small>{kind==='history'?t('control.branch_count',{count:1}):kind==='sketch'?t('control.sketch_subtitle',{number:page.number}):t('control.lock_subtitle',{count:status?.drift_total??status?.drift.length??0,chapter,threshold:Math.round((status?.threshold||.9)*100)})}</small></div><button type="button" class="mv-iconlink" onclick={onClose} aria-label={t('close')}><i class="ti ti-x" aria-hidden="true"></i></button></div>
 <div class="mv-ed__inspector-scroll">
  {#if loading}<p class="mv-ed__help mv-ed__pad" role="status">{t('control.loading')}</p>{/if}
  {#if kind==='history'}
   <section class="mv-ed__property"><strong>{t('control.branches')}</strong><div class="mv-control__branch"><span><i class="ti ti-git-branch" aria-hidden="true"></i> main</span><span class="mv-ed__help">{t('control.current')}</span></div></section>
   {#each versions as v (v.id)}
    <article class="mv-ed__version mv-control__version" data-version={v.number} class:selected={selected?.id===v.id}>
     <i class={`ti ti-${v.actor_kind==='agent'?'robot':v.action==='lock'?'lock':v.action==='generate_layer'?'sparkles':'history'}`} aria-hidden="true"></i>
     <button type="button" class="mv-control__version-pick" aria-pressed={selected?.id===v.id} onclick={()=>selected=v}>
      <strong>{t(`history.action.${v.action}`)===`history.action.${v.action}`?t('control.saved_change'):t(`history.action.${v.action}`)}</strong>
      <span>{t('history.version',{number:v.number})} · <time datetime={v.created_at}>{new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:'UTC'}).format(new Date(v.created_at))} UTC</time></span>
     </button>
     <Button small variant="bare" disabled={!writable||busy||running||v.number===page.version} onclick={()=>onRestore(v)}>{t('control.restore')}</Button>
    </article>
   {:else}{#if !loading}<p class="mv-ed__help mv-ed__pad">{t('history.empty')}</p>{/if}{/each}
  {:else if kind==='sketch'}
   <section class="mv-ed__property"><strong>{t('control.source')}</strong><div class="mv-seg mv-seg--full">{#each ['upload','draw','camera'] as option}<button type="button" class="mv-seg__item" aria-pressed={source===option} disabled={option==='camera'||busy||running||!writable} title={option==='camera'?t('soon'):undefined} onclick={()=>{source=option;if(option==='upload')file?.click();}}>{t(`control.${option}`)}{#if option==='camera'}<span class="mv-soon">{t('soon')}</span>{/if}</button>{/each}</div><input class="mv-sr-only" bind:this={file} type="file" accept="image/png,image/jpeg,image/webp" aria-label={t('control.upload')} onchange={pickFile}/><p class="mv-ed__help">{t('control.sketch_limits')}</p></section>
   <section class="mv-ed__property"><label for="sketch-strength">{t('control.strength')}</label><div class="mv-control__range-labels"><span>{t('control.loose')}</span><output for="sketch-strength">{new Intl.NumberFormat(lang,{minimumFractionDigits:2,maximumFractionDigits:2}).format(strength)}</output><span>{t('control.exact')}</span></div><input id="sketch-strength" class="mv-slider" type="range" min="0.05" max="1" step="0.01" bind:value={strength} disabled={busy||running||!writable}/></section>
   <section class="mv-ed__property"><strong>{t('control.detect')} <span class="mv-soon">{t('soon')}</span></strong><label class="mv-check"><input type="checkbox" checked disabled/><span class="mv-check__box" aria-hidden="true"><i class="ti ti-check"></i></span><span>{t('control.kept_panels',{count:page.panels.length})}</span></label><label class="mv-check"><input type="checkbox" checked disabled/><span class="mv-check__box" aria-hidden="true"><i class="ti ti-check"></i></span><span>{t('control.kept_characters')}</span></label><label class="mv-check"><input type="checkbox" checked disabled/><span class="mv-check__box" aria-hidden="true"><i class="ti ti-check"></i></span><span>{t('control.kept_lettering')}</span></label><p class="mv-ed__help">{t('control.detect_hint')}</p></section>
   <section class="mv-ed__property"><strong>{t('control.finish')}</strong><div class="mv-seg mv-seg--full">{#each ['screentone','grey','colour'] as option}<button type="button" class="mv-seg__item" aria-pressed={finish===option} disabled={busy||running||!writable} onclick={()=>finish=option}>{t(`control.${option}`)}</button>{/each}</div></section>
  {:else}
   <section class="mv-ed__property"><strong>{t('control.references')}</strong><div class="mv-control__refs">{#each refs as ref (ref.id)}<figure><img src={ref.url} alt={t(`control.ref_${ref.kind}`)===`control.ref_${ref.kind}`?t('control.references'):t(`control.ref_${ref.kind}`)}/><figcaption>{t(`control.ref_${ref.kind}`)===`control.ref_${ref.kind}`?t('control.references'):t(`control.ref_${ref.kind}`)}</figcaption></figure>{/each}</div></section>
   <section class="mv-ed__property"><strong>{t('control.drifted')}</strong>{#each status?.drift||[] as d (d.layer_id)}<div class="mv-control__drift" class:selected={drift?.layer_id===d.layer_id}><label class="mv-check"><input type="checkbox" checked={chosen.includes(d.layer_id)} disabled={d.locked||busy||running||!writable||!chosen.includes(d.layer_id)&&chosen.length>=24} onchange={()=>toggle(d)}/><span class="mv-check__box" aria-hidden="true"><i class="ti ti-check"></i></span><span class="mv-sr-only">{t('control.select_panel',{panel:`${d.page_number}.${d.panel_number}`})}</span></label><button type="button" class="mv-control__drift-pick" onclick={()=>{drift=d;afterURL='';afterScore=undefined;}}>{#if d.url}<img src={d.url} alt=""/>{/if}<span>{d.page_number}.{d.panel_number}</span><span class="mv-control__score">{Math.round(d.score*100)}%{#if d.locked} · {t('lock')}{/if}</span></button></div>{:else}{#if !loading}<p class="mv-ed__help">{t(status?.score===undefined?'control.no_assessment':'control.no_drift')}</p>{/if}{/each}<p class="mv-ed__help">{t('control.selection_limit')}</p>{#if (status?.drift_total||0)>(status?.drift.length||0)}<p class="mv-ed__help">{t('control.first_drift_page')}</p>{/if}</section>
   <section class="mv-ed__property"><strong>{t('control.what_changes')}</strong><p class="mv-ed__help">{t('control.repair_scope',{name})}</p></section>
  {/if}
 </div>
 <div class="mv-ed__inspector-actions mv-control__actions" class:mv-control__actions--history={kind==='history'}>
  {#if running}<div role="status"><p>{t('control.generating')} · {Math.round((activeJob?.progress||0)*100)}%</p><progress class="mv-ed__progress" value={activeJob?.progress||0} max="1" aria-label={t('progress')}></progress></div>{/if}
  {#if activeJob?.state==='failed'||activeJob?.state==='canceled'}<p class="mv-notice mv-notice--error" role="alert">{t(`job.${activeJob.state}`)}</p>{/if}
  {#if kind==='history'}<Button full icon="git-branch" disabled>{t('control.new_branch')}<span class="mv-soon">{t('soon')}</span></Button><Button full icon="git-merge" disabled>{t('control.merge_branch')}<span class="mv-soon">{t('soon')}</span></Button>
  {:else}<div class="mv-route"><i class="ti ti-route" aria-hidden="true"></i><strong>{t('auto')}</strong><span class="mv-route__pick">{quoteText}</span></div><Button full variant="primary" icon={kind==='sketch'?'brush':'wand'} busy={busy} disabled={!writable||!quote||running||busy||kind==='sketch'&&!sketch||kind==='lockfix'&&!choices.length} onclick={()=>kind==='sketch'?void ink():void repair()}>{kind==='sketch'?t('control.ink_page'):t('control.fix_panels',{count:choices.length})}</Button>{#if quote}<p class="mv-ed__help">{t('control.quote_scope',{count:quote.quote.layers})}</p>{/if}{/if}
  {#if activeJob}<a class="mv-btn mv-btn--quiet mv-btn--sm" href={`/queue?job=${activeJob.id}`}>{t('variations.open_queue')}</a>{/if}
 </div>
</aside>
